      "type": "diagram",
      "svg": "<svg viewBox=\"0 0 1100 1100\">\n<rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n<text x=\"550\" y=\"75\" font-size=\"27\" fill=\"#ffd700\" text-anchor=\"middle\" font-weight=\"bold\">Where Does PLG Still Hit a Chasm?</text>\n<rect x=\"130\" y=\"180\" width=\"840\" height=\"170\" fill=\"#10b981\"/>\n<text x=\"550\" y=\"230\" font-size=\"18\" fill=\"#1a1a2e\" text-anchor=\"middle\" font-weight=\"bold\">Grassroots usage still needs its own</text>\n<text x=\"550\" y=\"262\" font-size=\"18\" fill=\"#1a1a2e\" text-anchor=\"middle\" font-weight=\"bold\">enterprise-grade whole product: SSO,</text>\n<text x=\"550\" y=\"294\" font-size=\"18\" fill=\"#1a1a2e\" text-anchor=\"middle\" font-weight=\"bold\">admin controls, compliance certification</text>\n<rect x=\"130\" y=\"380\" width=\"840\" height=\"90\" fill=\"#888\"/>\n<text x=\"550\" y=\"435\" font-size=\"18\" fill=\"#ffffff\" text-anchor=\"middle\">Freemium products cannot grow without sales teams</text>\n<rect x=\"130\" y=\"490\" width=\"840\" height=\"90\" fill=\"#888\"/>\n<text x=\"550\" y=\"545\" font-size=\"18\" fill=\"#ffffff\" text-anchor=\"middle\">Pricing is always the only barrier</text>\n<rect x=\"130\" y=\"600\" width=\"840\" height=\"90\" fill=\"#888\"/>\n<text x=\"550\" y=\"655\" font-size=\"18\" fill=\"#ffffff\" text-anchor=\"middle\">Marketing budgets are inherently too small</text>\n<text x=\"550\" y=\"780\" font-size=\"19\" fill=\"#888\" text-anchor=\"middle\">The enterprise-readiness checklist is the modern whole product</text>\n</svg>",
